// Auto-generated by r2factor. Manual edits will be overwritten on next split.

pub(super) const CHART_WIDTH: f32 = 800.0;

pub(super) const CHART_HEIGHT: f32 = 400.0;

pub(super) const CHART_LEFT_MARGIN: f32 = 50.0;

pub(super) const CHART_RIGHT_MARGIN: f32 = 20.0;

pub(super) const CHART_TOP_MARGIN: f32 = 10.0;

pub(super) const CHART_BOTTOM_MARGIN: f32 = 40.0;

pub(super) const GPUI_PX_MARGIN_TOP: f32 = 10.0;

pub(super) const MIN_FREQ: f64 = sotf_plugins::AUDIBLE_MIN_FREQ;

pub(super) const MAX_FREQ: f64 = sotf_plugins::AUDIBLE_MAX_FREQ;

pub(super) const MIN_DB: f64 = -24.0;

pub(super) const MAX_DB: f64 = 24.0;

pub(super) const CONTROL_POINT_RADIUS: f32 = 10.0;

/// Calculate plot width (accounting for legend space)
pub(super) fn calculate_plot_width() -> f32 {
    // Simple calculation - no legend for this chart
    CHART_WIDTH - CHART_LEFT_MARGIN - CHART_RIGHT_MARGIN - 150.0 // Legend space
}

/// Convert frequency (Hz) to x pixel position
pub(super) fn freq_to_x(freq: f64, plot_width: f32) -> f32 {
    let log_min = MIN_FREQ.ln();
    let log_max = MAX_FREQ.ln();
    let t = (freq.ln() - log_min) / (log_max - log_min);
    CHART_LEFT_MARGIN + (t as f32) * plot_width
}

/// Convert x pixel position to frequency (Hz)
pub(super) fn x_to_freq(x: f32, plot_width: f32) -> f64 {
    let t = ((x - CHART_LEFT_MARGIN) / plot_width).clamp(0.0, 1.0) as f64;
    let log_min = MIN_FREQ.ln();
    let log_max = MAX_FREQ.ln();
    (log_min + t * (log_max - log_min)).exp()
}

/// Convert level (dB) to y pixel position
pub(super) fn level_to_y(level_db: f64) -> f32 {
    let plot_height = CHART_HEIGHT - GPUI_PX_MARGIN_TOP - CHART_BOTTOM_MARGIN;
    let t = (MAX_DB - level_db) / (MAX_DB - MIN_DB);
    CHART_TOP_MARGIN + (t as f32) * plot_height
}

/// Convert y pixel position to level (dB)
pub(super) fn y_to_level(y: f32) -> f64 {
    let plot_height = CHART_HEIGHT - GPUI_PX_MARGIN_TOP - CHART_BOTTOM_MARGIN;
    let t = ((y - CHART_TOP_MARGIN) / plot_height).clamp(0.0, 1.0) as f64;
    MAX_DB - t * (MAX_DB - MIN_DB)
}
